import{_ as a,H as e,f as n,i}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"22 | 如何使用ArgoCD快速打造生产可用的GitOps工作流？","description":"","frontmatter":{},"headers":[{"level":2,"title":"ArgoCD","slug":"argocd","link":"#argocd","children":[{"level":3,"title":"安装 ArgoCD","slug":"安装-argocd","link":"#安装-argocd","children":[]},{"level":3,"title":"安装 ArgoCD CLI","slug":"安装-argocd-cli","link":"#安装-argocd-cli","children":[]},{"level":3,"title":"本地访问 ArgoCD","slug":"本地访问-argocd","link":"#本地访问-argocd","children":[]}]},{"level":2,"title":"GitOps 工作流总览","slug":"gitops-工作流总览","link":"#gitops-工作流总览","children":[]},{"level":2,"title":"创建 ArgoCD 应用","slug":"创建-argocd-应用","link":"#创建-argocd-应用","children":[{"level":3,"title":"配置 ArgoCD 仓库访问权限（可选）","slug":"配置-argocd-仓库访问权限-可选","link":"#配置-argocd-仓库访问权限-可选","children":[]},{"level":3,"title":"创建 ArgoCD 应用","slug":"创建-argocd-应用-1","link":"#创建-argocd-应用-1","children":[]},{"level":3,"title":"查看 ArgoCD 同步状态","slug":"查看-argocd-同步状态","link":"#查看-argocd-同步状态","children":[]},{"level":3,"title":"访问应用","slug":"访问应用","link":"#访问应用","children":[]}]},{"level":2,"title":"连接 GitOps 工作流","slug":"连接-gitops-工作流","link":"#连接-gitops-工作流","children":[{"level":3,"title":"体验 GitOps 工作流","slug":"体验-gitops-工作流","link":"#体验-gitops-工作流","children":[]}]},{"level":2,"title":"生产建议","slug":"生产建议","link":"#生产建议","children":[{"level":3,"title":"建议一：修改默认密码","slug":"建议一-修改默认密码","link":"#建议一-修改默认密码","children":[]},{"level":3,"title":"建议二：配置 Ingress 和 TLS","slug":"建议二-配置-ingress-和-tls","link":"#建议二-配置-ingress-和-tls","children":[]},{"level":3,"title":"建议三：使用 Webhook 触发 ArgoCD","slug":"建议三-使用-webhook-触发-argocd","link":"#建议三-使用-webhook-触发-argocd","children":[]},{"level":3,"title":"建议四：将源码仓库和应用定义仓库分离","slug":"建议四-将源码仓库和应用定义仓库分离","link":"#建议四-将源码仓库和应用定义仓库分离","children":[]},{"level":3,"title":"建议五：加密 GitOps 中存储的秘钥","slug":"建议五-加密-gitops-中存储的秘钥","link":"#建议五-加密-gitops-中存储的秘钥","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"云原生架构与GitOps实战/22｜如何使用ArgoCD快速打造生产可用的GitOps工作流？.md","filePath":"云原生架构与GitOps实战/22｜如何使用ArgoCD快速打造生产可用的GitOps工作流？.md","lastUpdated":1795538134000}'),p={name:"云原生架构与GitOps实战/22｜如何使用ArgoCD快速打造生产可用的GitOps工作流？.md"};function t(l,s,o,r,c,h){return e(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="_22-如何使用argocd快速打造生产可用的gitops工作流" tabindex="-1">22 | 如何使用ArgoCD快速打造生产可用的GitOps工作流？ <a class="header-anchor" href="#_22-如何使用argocd快速打造生产可用的gitops工作流" aria-label="Permalink to &quot;22 | 如何使用ArgoCD快速打造生产可用的GitOps工作流？&quot;">​</a></h1><p>你好，我是王炜。</p><p>在之前的课程中，我们学习了如何使用 Kustomize 和 Helm 和来定义应用。其中，Helm Chart在实际工作中使用较多，它有两种存储方式，一种是以源码的方式存储在 Git 仓库中，另一种是以 tgz 压缩包的方式存储在专用的 OCI 仓库中。</p><p>此外，在自动化镜像构建部分，我还向你介绍了如何使用 GitHub Action、GitLab CI 以及自托管 Tekton 来自动构建镜像。</p><p>当我们具备这些 GitOps 的核心基础后，接下来我们就可以根据实际场景，选择合适的技术栈来构建 GitOps 流水线了。</p><p>在这节课，我仍然会以示例应用为例，使用 GitHub Action 和 Helm 分别作为自动构建镜像和应用定义的工具，并通过 ArgoCD 来构建一个完整的 GitOps 工作流。</p><p>在开始今天的学习之前，你需要准备好下面这几个条件。</p><ul><li><p>按照第 2 讲的内容在本地配置好 Kind 集群，安装 Ingress-Nginx，并暴露 80 和 443 端口。</p></li><li><p>配置好 Kubectl，使其能够访问 Kind 集群。</p></li><li><p>克隆 kubernetes-example 示例应用代码并推送到自己的 GitHub 仓库中，然后按照第16 讲的内容配置好 GitHub Action 和 DockerHub Registry。</p></li></ul><h2 id="argocd" tabindex="-1">ArgoCD <a class="header-anchor" href="#argocd" aria-label="Permalink to &quot;ArgoCD&quot;">​</a></h2><p>在“从零上手 GitOps”这一章，我使用了 FluxCD 来构建 GitOps 流水线。FluxCD 的主要特点是比较轻量，但同时也缺少友好的 UI 控制台。相比较而言，在社区和维护方面，ArgoCD 更为活跃。所以，在生产环境下，我推荐你使用 ArgoCD 来构建 GitOps 工作流。</p><h3 id="安装-argocd" tabindex="-1">安装 ArgoCD <a class="header-anchor" href="#安装-argocd" aria-label="Permalink to &quot;安装 ArgoCD&quot;">​</a></h3><p>要使用 ArgoCD，首先需要在 Kind 集群安装它，你可以通过下面的命令来安装。</p><p>首先，创建 argocd 命名空间。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl create namespace argocd</span></span>
<span class="line"><span>namespace/argocd created</span></span></code></pre></div><p>然后，部署 ArgoCD。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl apply -n argocd -f https://ghproxy.com/https://raw.githubusercontent.co</span></span>
<span class="line"><span>customresourcedefinition.apiextensions.k8s.io/applications.argoproj.io created</span></span>
<span class="line"><span>customresourcedefinition.apiextensions.k8s.io/applicationsets.argoproj.io created</span></span>
<span class="line"><span>customresourcedefinition.apiextensions.k8s.io/appprojects.argoproj.io created</span></span>
<span class="line"><span>......</span></span></code></pre></div><p>最后，等待 argocd 命名空间所有的工作负载处于就绪状态。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl wait --for=condition=Ready pods --all -n argocd --timeout 300s</span></span>
<span class="line"><span>pod/argocd-application-controller-0 condition met</span></span>
<span class="line"><span>pod/argocd-applicationset-controller-57bfc6fdb8-x5jxc condition met</span></span>
<span class="line"><span>......</span></span></code></pre></div><p>请注意，由于云厂商 Kubernetes 版本存在差异，所以如果你在安装过程中发现 argocd-repo-server 工作负载一直无法启动，可以尝试删除 argocd-repo-server DeploymentseccompProfile 节点的内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: apps/v1</span></span>
<span class="line"><span>kind: Deployment</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: argocd-repo-server</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> template:</span></span>
<span class="line"><span>   spec:</span></span>
<span class="line"><span>     securityContext:</span></span>
<span class="line"><span>       seccompProfile:</span></span>
<span class="line"><span>         type: RuntimeDefault</span></span></code></pre></div><h3 id="安装-argocd-cli" tabindex="-1">安装 ArgoCD CLI <a class="header-anchor" href="#安装-argocd-cli" aria-label="Permalink to &quot;安装 ArgoCD CLI&quot;">​</a></h3><p>为了更加方便地配置 ArgoCD，官方还为我们提供了 CLI 工具。不同操作系统的安装方法有所差异，这里以 MacOS 和 Windows 为例简单介绍。</p><p>MacOS 可以通过 Brew 来安装。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ brew install argocd</span></span></code></pre></div><p>也可以在这个链接下载最新版本的 Binary 二进制文件，并移动到 /usr/local/bin/ 目录下。</p><p>Windows 则需要在下载过后，将可执行文件移动到 PATH 下。</p><p>更详细的方法可以查看这份文档。</p><h3 id="本地访问-argocd" tabindex="-1">本地访问 ArgoCD <a class="header-anchor" href="#本地访问-argocd" aria-label="Permalink to &quot;本地访问 ArgoCD&quot;">​</a></h3><p>要在本地访问 ArgoCD，最简单的方式是通过端口转发来完成。你可以使用下面的命令来进行端口转发。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl port-forward service/argocd-server 8080:80 -n argocd</span></span>
<span class="line"><span>Forwarding from 127.0.0.1:8080 -&gt; 8080</span></span>
<span class="line"><span>Forwarding from [::1]:8080 -&gt; 8080</span></span></code></pre></div><p>接下来，使用浏览器打开：<a href="http://127.0.0.1:8080" target="_blank" rel="noreferrer">http://127.0.0.1:8080</a>，这样就可以访问 ArgoCD 控制台了，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/1.png" alt=""></a></p><p>ArgoCD 的默认账号为 admin，密码可以通过下面的命令来获取。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl -n argocd get secret argocd-initial-admin-secret -o jsonpath=&quot;{.data.pa</span></span>
<span class="line"><span>Gn4b2PFG6vKm1ADm</span></span></code></pre></div><p>登录后，即可访问 ArgoCD 的控制台。</p><h2 id="gitops-工作流总览" tabindex="-1">GitOps 工作流总览 <a class="header-anchor" href="#gitops-工作流总览" aria-label="Permalink to &quot;GitOps 工作流总览&quot;">​</a></h2><p>到这里，你是不是已经迫不及待想要构建工作流了？别急，在创建 GitOps 工作流之前，我们先来认识一下一个完整 GitOps 工作流都需要哪些关键步骤。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/2.png" alt=""></a></p><p>我们可以把这个完整的 GitOps 工作流分成三个部分来看。</p><p>第一部分是开发者推送代码到 GitHub 仓库，然后触发 GitHub Action 自动构建。</p><p>第二部分是 GitHub Action 自动构建，它包括下面三个步骤。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 构建示例应用的镜像。</span></span>
<span class="line"><span>2. 将示例应用的镜像推送到 Docker Registry 镜像仓库。</span></span>
<span class="line"><span>3. 更新代码仓库中 Helm Chart values.yaml 文件的镜像版本。</span></span></code></pre></div><p>第三部分的核心是 ArgoCD，它包括下面两个步骤。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4. 通过定期 Poll 的方式持续拉取 Git 仓库，并判断是否有新的 commit。</span></span>
<span class="line"><span>5. 从 Git 仓库获取 Kubernetes 对象，与集群对象进行实时比较，自动更新集群内有差异的资源。</span></span></code></pre></div><p>在之前的课程中，我们已经为示例应用创建好了 GitHub Action 来自动构建镜像，但还缺少自动更新 Helm Chart values.yaml 文件的镜像版本逻辑，我会在稍后进行配置。</p><p>现在，我们开始创建 GitOps 工作流中的第三部分，也就是创建 ArgoCD 应用，实现Kubernetes 资源的自动同步。</p><h2 id="创建-argocd-应用" tabindex="-1">创建 ArgoCD 应用 <a class="header-anchor" href="#创建-argocd-应用" aria-label="Permalink to &quot;创建 ArgoCD 应用&quot;">​</a></h2><p>我们以示例应用为例子来创建 ArgoCD 应用，这里主要分成两个步骤。</p><ol><li><p>配置仓库访问权限。</p></li><li><p>创建 ArgoCD 应用。</p></li></ol><p>其中，如果你的示例应用仓库是公开的，可以跳过第一步。</p><h3 id="配置-argocd-仓库访问权限-可选" tabindex="-1">配置 ArgoCD 仓库访问权限（可选） <a class="header-anchor" href="#配置-argocd-仓库访问权限-可选" aria-label="Permalink to &quot;配置 ArgoCD 仓库访问权限（可选）&quot;">​</a></h3><p>在实际场景下，我们存放应用定义的仓库一般都是私有仓库，这就需要为 ArgoCD 配置仓库访问权限。</p><p>你可以通过下面的 ArgoCD CLI 工具来为 ArgoCD 添加仓库访问权限。</p><p>在使用 ArgoCD CLI 工具之前，你需要先执行 argocd login 命令登录。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ argocd login 127.0.0.1:8080 --insecure</span></span>
<span class="line"><span>Username: admin</span></span>
<span class="line"><span>Password:</span></span>
<span class="line"><span>&#39;admin:login&#39; logged in successfully</span></span></code></pre></div><p>注意，这里我们指定了 ArgoCD 的服务端地址为 127.0.0.1:8080，并且使用了 --insecur 参数来跳过 SSL 认证，你需要保持在上面运行的端口转发命令才能够顺利登录。</p><p>登录成功后，通过 argocd repo add 命令添加你的示例应用仓库。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ argocd repo add https://github.com/lyzhang1999/kubernetes-example.git --usernam</span></span>
<span class="line"><span>Repository &#39;https://github.com/lyzhang1999/kubernetes-example.git&#39; added</span></span>
<span class="line"><span>这里要注意将仓库地址修改为你实际的 GitHub 仓库地址，并将 $USERNAME 替换为 GitHub</span></span>
<span class="line"><span>账户 ID，将 $PASSWORD 替换为 GitHub Personal Token。你可以在这个页面创建 GitHub</span></span></code></pre></div><p>Personal Token，并赋予仓库相关权限，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/3.png" alt=""></a></p><h3 id="创建-argocd-应用-1" tabindex="-1">创建 ArgoCD 应用 <a class="header-anchor" href="#创建-argocd-应用-1" aria-label="Permalink to &quot;创建 ArgoCD 应用&quot;">​</a></h3><p>接下来，就可以创建 ArgoCD 应用了。ArgoCD 同时支持使用 Helm Chart、Kustomize 和Manifest 来创建应用，这里我们以示例应用的 Helm Chart 为例。</p><p>你可以通过 argocd app create 命令来创建应用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ argocd app create example --sync-policy automated --repo https://github.com/lyz</span></span>
<span class="line"><span>application &#39;example&#39; created</span></span></code></pre></div><p>这里我简单解释一下每个参数的作用。</p><p>–sync-policy 参数代表设置自动同步策略。automated 的含义是自动同步，也就是说当集群内的资源和 Git 仓库 Helm Chart 定义的资源有差异时，ArgoCD 会自动执行同步操作，实时确保集群资源和 Helm Chart 的一致性。</p><p>–repo 参数表示 Helm Chart 的仓库地址。这里的值是示例应用的仓库地址，注意需要替换成你实际的 Git 仓库地址。</p><p>–revision 参数表示需要跟踪的分支或者 Tag，这里我们让 ArgoCD 跟踪 main 分支的改动。</p><p>–path 参数表示 Helm Chart 的路径。在示例应用中，存放 Helm Chart 的目录是 helm 目录。</p><p>–dest-namespace 参数表示命名空间。这里指定了 gitops-example 命名空间，注意，这是一个不存在的命名空间，所以我们额外通过 --sync-option 参数来让 ArgoCD 自动创建这个命名空间。</p><p>最后，–dest-server 参数表示要部署的集群，<a href="https://kubernetes.default.svc" target="_blank" rel="noreferrer">https://kubernetes.default.svc</a> 表示 ArgoCD所在的集群。</p><h3 id="查看-argocd-同步状态" tabindex="-1">查看 ArgoCD 同步状态 <a class="header-anchor" href="#查看-argocd-同步状态" aria-label="Permalink to &quot;查看 ArgoCD 同步状态&quot;">​</a></h3><p>创建好应用之后，GitOps 工作流中的自动同步部分也就建立起来了。现在，你可以打开ArgoCD 控制台，进入左侧的“Application”菜单来查看示例应用详情。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/4.png" alt=""></a></p><p>在应用详情页面，我们需要重点关注三个状态。</p><ol><li>APP HEALTH：应用整体的健康状态，它包含下面三个值。</li></ol><ul><li><p>Progressing：处理中1.</p></li><li><p>Healthy：健康状态2.</p></li><li><p>Degraded：宕机3.</p></li></ul><ol start="2"><li>CURRENT SYNC STATUS： 应用定义和集群对象的差异状态，也包含下面三个值。</li></ol><ul><li><p>Synced：完全同步1.</p></li><li><p>OutOfSync：存在差异2.</p></li><li><p>Unknown：未知3.</p></li></ul><ol start="3"><li>LAST SYNC RESULT：最后一次同步到 Git 仓库的信息，包括 Commit ID 和提交者信息。</li></ol><h3 id="访问应用" tabindex="-1">访问应用 <a class="header-anchor" href="#访问应用" aria-label="Permalink to &quot;访问应用&quot;">​</a></h3><p>当应用健康状态变为 Healthy 之后，我们就可以访问应用了。</p><p>在这之前，如果你已经在 example 命名空间下手动部署了示例应用，为了避免 Ingress 策略冲突，你需要先删除这个命名空间。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ns example</span></span></code></pre></div><p>然后，使用浏览器访问 <a href="http://127.0.0.1" target="_blank" rel="noreferrer">http://127.0.0.1</a>，你应该能看到示例应用的界面，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/5.png" alt=""></a></p><p>到这里，ArgoCD 部分就配置完成了。</p><h2 id="连接-gitops-工作流" tabindex="-1">连接 GitOps 工作流 <a class="header-anchor" href="#连接-gitops-工作流" aria-label="Permalink to &quot;连接 GitOps 工作流&quot;">​</a></h2><p>在完成 ArgoCD 的应用配置之后，我们就已经将示例应用的 Helm Chart 定义和集群资源关联起来了，但整个 GitOps 工作流还缺少非常重要的一部分，就是我在上面提到的自动更新Helm Chart values.yaml 文件镜像版本的部分，我在下面这张示意图中用“”把这个环节标记了出来。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/6.png" alt=""></a></p><p>在这部分工作流没有打通之前，提交的新代码虽然会构建出新的镜像，但是 Helm Chart 定义的镜像版本并不会产生变化，这会导致 ArgoCD 不能自动更新集群内工作负载的镜像版本。</p><p>要解决这个问题，我们还需要在 GitHub Action 中添加自动修改 Helm Chart 并重新推送到仓库操作。</p><p>接下来，我们修改示例应用的 .github/workflows/build.yaml 文件，在“Build frontend andpush”阶段后面添加一个新的阶段，代码如下。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> helm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">values</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.yaml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> uses: fjogeleit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">yaml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-update-action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@main</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   valueFile: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;helm/values.yaml&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   commitChange: true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   branch: main</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">   message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Update Image Version to \${​{ steps.vars.outputs.sha_short }​}&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">   changes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;backend.tag&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${​{ steps.vars.outputs.sha_short }​}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;frontend.tag&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${​{ steps.vars.outputs.sha_short }​}&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     }</span></span></code></pre></div><p>在这里，我使用了 GitHub Action 中 yaml-update-action 插件来修改 values.yaml 文件并把它推送到仓库。如果你是使用 GitLab 或者 Tekton 构建镜像，可以调用 yq 命令行工具来修改YAML 文件，再使用 git 命令行将变更推送到仓库。</p><p>到这里，一个完整的 GitOps 工作流就建立好了。</p><h3 id="体验-gitops-工作流" tabindex="-1">体验 GitOps 工作流 <a class="header-anchor" href="#体验-gitops-工作流" aria-label="Permalink to &quot;体验 GitOps 工作流&quot;">​</a></h3><p>接下来，你可以尝试修改 frontend/src/App.js 文件，例如修改文件第 49 行的“Hi! I am ageekbang”。修改完成后，将代码推送到 GitHub 仓库 main 分支，此时，GitHub Action 会自动构建镜像，并且还会更新代码仓库中 Helm values.yaml 文件的镜像版本。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/7.png" alt=""></a></p><p>ArgoCD 默认每 3 分钟会拉取仓库检查是否有新的提交，你也可以在 ArgoCD 控制台手动点击Sync 按钮来触发同步。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/8.png" alt=""></a></p><p>ArgoCD 同步完成后，我们可以在“LAST SYNC RESULT”一栏中看到 GitHub Action 修改values.yaml 的提交记录，当应用状态为 Healthy 时，我们就可以访问新的应用版本了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/9.png" alt=""></a></p><p>从截图可以看出，前端界面输出内容为“Hi, I am GitOps workflow”，说明 ArgoCD 已经将新版本的应用部署到集群中了。</p><p>自此，我们体验了提交代码到构建镜像、修改应用定义和更新自动化的全流程。</p><h2 id="生产建议" tabindex="-1">生产建议 <a class="header-anchor" href="#生产建议" aria-label="Permalink to &quot;生产建议&quot;">​</a></h2><p>在生产环境下，我也给你提几个 ArgoCD 的配置建议，你可以根据实际情况来配置。</p><h3 id="建议一-修改默认密码" tabindex="-1">建议一：修改默认密码 <a class="header-anchor" href="#建议一-修改默认密码" aria-label="Permalink to &quot;建议一：修改默认密码&quot;">​</a></h3><p>默认情况下，ArgoCD 会在部署时生成一个随机密码，为了方便记忆和增加密码强度，你可以使用下面的命令来修改密码。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ argocd account </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">update-password</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">***</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Enter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> of currently logged </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">admin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">***</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Enter new </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">admin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>要注意是的是，在修改密码前，你需要先使用 argocd login 登录到 ArgoCD 服务端。</p><h3 id="建议二-配置-ingress-和-tls" tabindex="-1">建议二：配置 Ingress 和 TLS <a class="header-anchor" href="#建议二-配置-ingress-和-tls" aria-label="Permalink to &quot;建议二：配置 Ingress 和 TLS&quot;">​</a></h3><p>在生产环境下，为了更方便地访问 ArgoCD，你可以为它配置 Ingress，你可以将下面的Ingress 对象部署到集群内。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: networking.k8s.io/v1</span></span>
<span class="line"><span>kind: Ingress</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: argocd-server-ingress</span></span>
<span class="line"><span> namespace: argocd</span></span>
<span class="line"><span> annotations:</span></span>
<span class="line"><span>   cert-manager.io/cluster-issuer: letsencrypt-prod</span></span>
<span class="line"><span>   kubernetes.io/ingress.class: nginx</span></span>
<span class="line"><span>   kubernetes.io/tls-acme: &quot;true&quot;</span></span>
<span class="line"><span>   nginx.ingress.kubernetes.io/ssl-passthrough: &quot;true&quot;</span></span>
<span class="line"><span>   nginx.ingress.kubernetes.io/backend-protocol: &quot;HTTPS&quot;</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> rules:</span></span>
<span class="line"><span> - host: argocd.example.com</span></span>
<span class="line"><span>   http:</span></span>
<span class="line"><span>     paths:</span></span>
<span class="line"><span>     - path: /</span></span>
<span class="line"><span>       pathType: Prefix</span></span>
<span class="line"><span>       backend:</span></span>
<span class="line"><span>         service:</span></span>
<span class="line"><span>           name: argocd-server</span></span>
<span class="line"><span>           port:</span></span>
<span class="line"><span>             name: https</span></span>
<span class="line"><span> tls:</span></span>
<span class="line"><span> - hosts:</span></span>
<span class="line"><span>   - argocd.example.com</span></span>
<span class="line"><span>   secretName: argocd-secret # do not change, this is provided by Argo CD</span></span></code></pre></div><p>此外，你还需要安装 Cert-manager，具体方法可以参考第 19 讲的内容。</p><h3 id="建议三-使用-webhook-触发-argocd" tabindex="-1">建议三：使用 Webhook 触发 ArgoCD <a class="header-anchor" href="#建议三-使用-webhook-触发-argocd" aria-label="Permalink to &quot;建议三：使用 Webhook 触发 ArgoCD&quot;">​</a></h3><p>在这节课的例子中，我们在创建应用的时候提供了参数 --sync-policy=automated。这时候，ArgoCD 会默认以 3 分钟一次的频率来自动拉取仓库的更改，在生产环境下，这个同步频率可能并不能满足快速发布的要求。</p><p>如果 ArgoCD 可以在公网进行访问，那么你就可以使用 ArgoCD 提供的 Webhook 触发方式来解决这个问题了，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/10.png" alt=""></a></p><p>和主动 Poll 模型不同的是，源码仓库在收到开发者推送代码的事件后，将实时通过 HTTP 请求来通知 ArgoCD，也就是图中红色字体的部分。</p><p>要使用 Webhook 通知的方式，首先你需要在源码仓库进行配置。以 GitHub 为例，首先进入仓库的“Settings”页面，点击左侧的“Webhook”菜单进入配置页面，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/22/11.png" alt=""></a></p><p>在 Payload URL 中输入你的 ArgoCD Server 外网访问域名，/api/webhook ArgoCD 专门用于接收外部 Webhook 消息的固定路径。</p><p>Content type 选择 application/json，并在 Secret 中输入你要配置的 Webhook 的密钥，这个密钥需要提供给 ArgoCD 来校验 Webhook 来源是否合法。</p><p>接下来点击“Add webhook” 就可以保存了。</p><p>接下来，你还需要为 ArgoCD 提供 GitHub Webhook 密钥，使用下面的命令来编辑 argocd-secret 对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl edit secret argocd-secret -n argocd</span></span></code></pre></div><p>并将 GitHub Webhook 的密钥加入到 Secret 对象的内容里。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: Secret</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: argocd-secret</span></span>
<span class="line"><span> namespace: argocd</span></span>
<span class="line"><span>type: Opaque</span></span>
<span class="line"><span>data:</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>stringData:</span></span>
<span class="line"><span> # 加入这一项</span></span>
<span class="line"><span> webhook.github.secret: my-secret</span></span></code></pre></div><p>注意，stringData 可以直接输入 Webhook Secret 内容而不需要进行 Base64 编码。</p><p>如果你使用的是其他的代码托管平台，例如 GitLab，可以参考这份文档进行配置。</p><h3 id="建议四-将源码仓库和应用定义仓库分离" tabindex="-1">建议四：将源码仓库和应用定义仓库分离 <a class="header-anchor" href="#建议四-将源码仓库和应用定义仓库分离" aria-label="Permalink to &quot;建议四：将源码仓库和应用定义仓库分离&quot;">​</a></h3><p>为了方便演示，我将示例应用的源码和 Helm Chart 存储在了同一个 Git 仓库，实际上，这并不是一个好的实践。</p><p>这种方案有两个比较大的问题。首先，当我们手动修改 Helm Chart 并推送到 Git 仓库之后，在业务代码不变的情况下也会触发应用镜像构建，这个过程是没有必要的。</p><p>其次，在有一定规模的团队中，开发和发布过程是分开的，应用定义仓库一般只有基础架构部门或者 SRE 部门具有修改权限，将源码和应用定义放在同一个 Git 仓库不利于权限控制，开发者也很容易误操作。</p><p>所以，基于上面这两个问题，我强烈建议你将业务代码和应用定义分开存储。</p><h3 id="建议五-加密-gitops-中存储的秘钥" tabindex="-1">建议五：加密 GitOps 中存储的秘钥 <a class="header-anchor" href="#建议五-加密-gitops-中存储的秘钥" aria-label="Permalink to &quot;建议五：加密 GitOps 中存储的秘钥&quot;">​</a></h3><p>在示例应用中，我使用的是 DockerHub 公开仓库，所以 Kubernetes 集群不需要镜像拉取凭据就可以拉取到镜像。</p><p>在实际生产环境下，一般我们会使用内部自建例如 Harbor 私有仓库。所以在大部分情况下，我们会在 Helm Chart 里增加一个包含镜像拉取凭据的 Secret 对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: Secret</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: regcred</span></span>
<span class="line"><span>type: kubernetes.io/dockerconfigjson</span></span>
<span class="line"><span>data:</span></span>
<span class="line"><span> .dockerconfigjson: &gt;-</span></span>
<span class="line"><span>   eyJhdXRocyI6eyJodHRwczovL2luZGV4LmRvY2tlci5pby92MS8iOnsidXNlcm5hbWUiOiJseXpoY</span></span></code></pre></div><p>这样，当 ArgoCD 部署应用时，会一并将拉取凭据部署到集群中，这就解决了镜像拉取权限的问题。</p><p>但是，Secret 对象并没有加密功能，这可能会导致凭据泄露。所以，我们需要对这些敏感信息进行加密处理。关于如何加密秘钥，我会在后续“多环境管理和安全”章节为你详细介绍。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在这节课，我以示例应用为例，将 GitHub Action、应用定义以及 ArgoCD 连接起来，构建了完整的 GitOps 工作流。</p><p>通过这个例子我们会发现，建立完整的 GitOps 工作流涉及到下面这几个技术：</p><ol><li><p>Docker 镜像</p></li><li><p>CI 构建</p></li><li><p>镜像仓库</p></li><li><p>应用定义</p></li><li><p>Kubernetes</p></li><li><p>ArgoCD</p></li></ol><p>在建立 GitOps 工作流的过程中，通常有两个难点。第一是如何进行技术选型和组合，第二是如何将它们连接起来。</p><p>我先总结一下如何解决第一个问题：技术选型和组合。</p><p>在这节课的例子中，我使用了 GitHub Action 作为 CI 构建工具，此外，你还可以选择 GitLabCI 或者自托管的 Tekton 。对于镜像仓库，我使用了 DockerHub 来存储镜像，你也可以使用GitHub Package 或者自建 Harbor 来存储镜像。最后，在应用定义方面，我使用了 HelmChart 作为例子，你还可以选择 Kustomize 甚至是 Kubernetes Manifest 。</p><p>在建立 GitOps 的过程中，你可以根据团队实际的情况，对这些技术栈任意组合。</p><p>对于如何连接的问题，它最底层的追问是，在构建好镜像并将其推送到镜像仓库之后，怎么通知 ArgoCD 部署新镜像版本。</p><p>在这节课的例子中，我在 GitHub Action 里修改了 values.yaml 文件，并将其推送到了 Git 仓库，所以会产生新的 commit，进而达到通知 ArgoCD 的效果。</p><p>这种方式虽然能解决问题，但在一些场景下可能并不适合。例如，在开发和发布相对独立的场景下，因为权限和安全的问题可能并不允许 CI 直接修改应用定义。在这种情况下，我们就可以使用另外一种方式来通知 ArgoCD，也就是 Argo CD Image Updater。它可以通过监听镜像版本的更新来触发 ArgoCD 同步，我们会在下一节课详细介绍。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后，给你留一道思考题吧。</p><p>在 ArgoCD 自动同步完成后，应用的“CURRENT SYNC STATUS”会从“Synced”很快变为“OutOfSync”，这是为什么呢？如何解决？</p><p>欢迎你给我留言交流讨论，你也可以把这节课分享给更多的朋友一起阅读。我们下节课见。</p>`,157)])])}const E=a(p,[["render",t]]);export{d as __pageData,E as default};
